commands:
  earn  --mbr MBR --pt N --ref REF
        prints the entry number
  bal   MBR
  hist  MBR
        entry, ref, points (tab separated)

  MBR   member number; @MBR is also accepted
  REF   [A-Za-z0-9-], 1..32 chars, once per ledger

environment:
  PTSCTL_HOME   ledger directory (required)
exit=0
